const n = $('Normalize Intake').item.json;
const htmlEscape = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
}[ch]));
const raw = $input.item.json;
const extractText = (value) => {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(extractText).filter(Boolean).join('\n');
  if (value && typeof value === 'object') {
    if (typeof value.text === 'string') return value.text;
    if (typeof value.output_text === 'string') return value.output_text;
    if (value.content) return extractText(value.content);
    if (value.output) return extractText(value.output);
  }
  return '';
};
let ai = raw.output ?? raw.text ?? raw.content ?? raw;
if (typeof ai === 'string') {
  const cleaned = ai.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  try { ai = JSON.parse(cleaned); } catch { ai = null; }
} else {
  const extracted = extractText(ai);
  const cleaned = extracted.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  if (cleaned) {
    try { ai = JSON.parse(cleaned); } catch { /* keep original object for validation fallback */ }
  }
}
const categories = ['Ops Automation','Sales/CRM','Finance/Admin','Marketing','Support','Data/Reporting','Other'];
const sizes = ['solo','micro','smb','mid','enterprise','unknown'];
const levels = ['low','medium','high','unknown'];
const budgets = ['none','low','medium','high','unknown'];
const reasons = [];
if (!ai || typeof ai !== 'object') reasons.push('AI output unparseable');
ai = ai || {};
const pickEnum = (value, allowed, fallback, label, aliases = {}) => {
  const v = typeof value === 'string' ? value.trim() : '';
  if (allowed.includes(v)) return v;
  const alias = aliases[v.toLowerCase()];
  if (alias) return alias;
  reasons.push(label + ' outside enum');
  return fallback;
};
let confidence = Number(ai.confidence);
if (!Number.isFinite(confidence)) { confidence = 0; reasons.push('confidence missing or nonnumeric'); }
confidence = Math.max(0, Math.min(1, confidence));
const need_summary = typeof ai.need_summary === 'string' ? ai.need_summary.trim() : '';
if (need_summary.length < 8) reasons.push('need_summary too sparse');
let welcome_message = typeof ai.welcome_message === 'string' ? ai.welcome_message.trim() : '';
if (welcome_message.length < 20) {
  welcome_message = 'Thank you for reaching out to Acme Automation. We received your automation request and will follow up with practical next steps shortly.';
  reasons.push('welcome_message fallback used');
}
if (welcome_message.length > 1200) welcome_message = welcome_message.slice(0, 1200);
const review_reason = [typeof ai.review_reason === 'string' ? ai.review_reason.trim() : '', ...reasons].filter(Boolean).join('; ');
const needs_review = ai.needs_human_review === true || confidence < 0.75 || reasons.length > 0;
const company = n.company || 'Unknown';
const email = n.email;
return { json: {
  submission_id: n.submission_id,
  status: needs_review ? 'Needs Review' : 'Approved',
  name: n.name || 'Unknown',
  company,
  company_html: htmlEscape(company),
  email,
  email_html: htmlEscape(email),
  raw_needs: n.raw_needs,
  raw_needs_html: htmlEscape(n.raw_needs),
  need_summary,
  need_summary_html: htmlEscape(need_summary),
  category: pickEnum(ai.category, categories, 'Other', 'category', { consulting: 'Other', automation: 'Ops Automation' }),
  company_size: pickEnum(ai.company_size, sizes, 'unknown', 'company_size', { small: 'smb', medium: 'mid', large: 'enterprise' }),
  urgency: pickEnum(ai.urgency, levels, 'unknown', 'urgency', { medium: 'medium', low: 'low', high: 'high' }),
  budget_signal: pickEnum(ai.budget_signal, budgets, 'unknown', 'budget_signal', { low: 'low', medium: 'medium', high: 'high' }),
  confidence,
  sensitive_held: false,
  sensitivity_flags: '',
  review_reason,
  review_reason_html: htmlEscape(review_reason),
  welcome_message,
  welcome_message_html: htmlEscape(welcome_message),
  welcome_sent: !needs_review,
  alert_sent: false,
  replay_count: 0,
  created_at: n.created_at,
  updated_at: new Date().toISOString(),
  model_version: n.model_version,
  raw_ai_output: JSON.stringify(ai).slice(0, 9000),
  execution_id: n.execution_id,
}};

const n = $('Normalize Intake').item.json;
const store = $getWorkflowStaticData('global');
store.lead_intake_claims = store.lead_intake_claims || {};
const claims = store.lead_intake_claims;
const now = Date.now();
const nowIso = new Date(now).toISOString();
const staleInProgressMs = 15 * 60 * 1000;
const claim = claims[n.submission_id];
const claimAge = claim?.claimed_at ? now - Date.parse(claim.claimed_at) : 0;
const activeClaim = claim && (claim.status !== 'in_progress' || claimAge < staleInProgressMs);
if (activeClaim) {
  return { json: {
    ...n,
    duplicate_claim: true,
    existing_record_id: claim.record_id || '',
    duplicate_status: claim.status || 'seen',
    first_execution_id: claim.first_execution_id || '',
    claimed_at: claim.claimed_at || '',
  }};
}
claims[n.submission_id] = {
  status: 'in_progress',
  claimed_at: nowIso,
  first_execution_id: n.execution_id,
  source: n.source,
};
return { json: {
  ...n,
  duplicate_claim: false,
  duplicate_status: '',
  existing_record_id: '',
  first_execution_id: n.execution_id,
  claimed_at: nowIso,
}};

